mapper.select:
SELECT MIN(recipe_id)
FROM the_full_order.tb_recipe_detail
WHERE menu_id = #{menu_id}

SELECT T.account_id, (SELECT JSON_ARRAYAGG(CONCAT_WS(' ',rd.ingredient_name_raw,im.ingredient_name_std,im.ingredient_name_raw)) FROM the_full_order.tb_account_recipe_detail rd LEFT JOIN the_full_order.tb_account_ingredient_master im ON im.account_id=rd.account_id AND im.ingredient_id=rd.ingredient_id WHERE rd.account_id=T.account_id AND rd.menu_id=T.menu_id) AS recipe_ingredient_names, T2.menu_img, CASE WHEN T2.menu_id IS NULL THEN 'N' ELSE 'Y' END AS standard_yn, T.menu_id, T.menu_name, T.del_yn, T.food_type, T.food_type_reason, DATE_FORMAT(T.created_at, '%Y-%m-%d') as created_at, T3.like, T.menu_type, T.menu_gubun, T.meal_plan_type, T.calories_per_serving, (SELECT CASE WHEN COUNT(*)>0 AND COUNT(c.cost_per_person)=COUNT(*) THEN ROUND(SUM(c.cost_per_person),4) END FROM () c WHERE c.account_id=T.account_id AND c.menu_id=T.menu_id) AS menu_cost_per_person, (SELECT CASE WHEN COUNT(*)>0 AND COUNT(c.cost_per_person)=COUNT(*) THEN 1 ELSE 0 END FROM () c WHERE c.account_id=T.account_id AND c.menu_id=T.menu_id) AS menu_cost_complete, (SELECT GROUP_CONCAT(CONCAT(COALESCE(c.ingredient_name,c.ingredient_id), ': ',c.missing_reason) SEPARATOR ', ') FROM () c WHERE c.account_id=T.account_id AND c.menu_id=T.menu_id AND c.cost_per_person IS NULL) AS menu_cost_reason FROM the_full_order.tb_account_menu_master T
LEFT JOIN the_full_order.tb_menu_master T2 ON T2.menu_id = T.menu_id LEFT JOIN the_full_order.tb_like_menu T3 ON T3.account_id = T.account_id AND T3.menu_id = T.menu_id WHERE T.account_id = #{account_id} AND ifnull(T.del_yn, 'N') = 'N'
AND T.meal_plan_type = #{meal_plan_type}
